"""Single declarative navigation registry.

This module intentionally contains no request, session, Firestore, or Flask
lookups. Availability and authorization are resolved by ``resolver.py``.
"""

from .constants import WORKSPACE_ACCOUNTING, WORKSPACE_GLOBAL, WORKSPACE_RRHH
from .models import NavigationItem, NavigationType


def _group(id, label, icon, workspace, order, **kwargs):
    return NavigationItem(
        id=id,
        label=label,
        icon=icon,
        workspace=workspace,
        order=order,
        type=NavigationType.GROUP.value,
        **kwargs,
    )


def _link(id, label, route, workspace, order, parent=None, **kwargs):
    return NavigationItem(
        id=id,
        label=label,
        route=route,
        workspace=workspace,
        order=order,
        parent=parent,
        **kwargs,
    )


